script:
// Fleet Audit -- self-contained. Everything lives in this one Custom HTML
// Block: no separate desk Page, no file under public/js. `root_element` is the
// shadow root Frappe gives this block; the html/style fields on this same
// record hold the markup and CSS.
//
// Plain DOM APIs throughout, not jQuery -- jQuery wrapping a ShadowRoot is not
// a pattern this codebase's other Custom HTML Blocks rely on (they use
// root_element.querySelector directly), so this does the same rather than
// assume jQuery handles a shadow root the way it handles a normal document.
//
// Reads app_apis.fleet_audit (ERPNext + Pilot + IM, reconciled and stored in
// app_apis_fleet_audit). Refresh re-runs that reconciliation; everything else
// here only reads the stored snapshot.

(function () {
	var root = root_element.querySelector(".fav");
	var filters = {
		imei: "", vehicle: "", customer: "", erp_status: "",
		on_pilot: "", on_pilot_1: "", on_pilot_2: "", on_im: "", sim_status: "", sim_msisdn: "",
		no_sim: "", sim_item: "", verdict: "",
		pilot_last_seen_from: "", pilot_last_seen_to: "",
		im_last_seen_from: "", im_last_seen_to: "",
		sim_last_seen_from: "", sim_last_seen_to: "",
	};
	var start = 0;
	var limit = 100;
	var summary = {};
	var options = {};
	var last_res = null;
	var refresh_watch = null;

	var el = {
		when: root.querySelector(".fav-when"),
		headright: root.querySelector(".fav-headright"),
		loadbar: root.querySelector(".fav-loadbar"),
		notes: root.querySelector(".fav-notes"),
		tiles: root.querySelector(".fav-tiles"),
		chips: root.querySelector(".fav-chips"),
		count: root.querySelector(".fav-count"),
		nosim: root.querySelector(".fav-nosim-box"),
		clear: root.querySelector(".fav-clear"),
		wrap: root.querySelector(".fav-wrap"),
		topscroll: root.querySelector(".fav-topscroll"),
		foot: root.querySelector(".fav-foot"),
	};

	function esc(v) {
		return frappe.utils.escape_html(String(v === undefined || v === null ? "" : v));
	}
	function num(v) {
		return (Number(v) || 0).toLocaleString();
	}
	function tone(verdict) {
		return (
			{
				"OK": "green",
				"Deleted but still live": "orange",
				"Missing on Pilot": "red",
				"Missing on IM": "red",
				"Missing on both": "red",
				"No platform": "yellow",
				"Unexpected platform": "yellow",
				"Not in ERP": "purple",
			}[verdict] || "gray"
		);
	}
	// What you would act on first, first. Alphabetical would put "Deleted but
	// still live" -- the one that costs money every month -- below "Missing on IM".
	var VERDICT_ORDER = [
		"Deleted but still live", "Missing on Pilot", "Missing on IM", "Missing on both",
		"No platform", "Unexpected platform", "Not in ERP", "No device serial", "Unmatchable ID",
		"Not checked", "OK",
	];

	// -------------------------------------------------------------- wiring

	el.clear.addEventListener("click", function (e) {
		e.preventDefault();
		Object.keys(filters).forEach(function (k) { filters[k] = ""; });
		start = 0;
		render_chips();
		load_rows();
	});

	// "No SIM" toggle -- above the table, not in the header, so it stays put
	// and visible while the table below it re-renders and scrolls. Checking it
	// clears the SIM No search box too (a typed number and "has no number"
	// contradict). render_rows() keeps this box in sync with filters.no_sim,
	// so a tile click or Clear filters unchecks it on its own.
	if (el.nosim) {
		el.nosim.addEventListener("change", function () {
			filters.no_sim = el.nosim.checked ? "1" : "";
			if (el.nosim.checked) filters.sim_msisdn = "";
			start = 0;
			render_chips();
			load_rows();
		});
	}

	el.headright.innerHTML =
		'<button class="btn btn-default btn-sm fav-refresh" title="Read ERPNext, Pilot and IM again">Fetch All</button>' +
		'<button class="btn btn-default btn-sm fav-upload-sim" style="margin-left:6px" ' +
			'title="Upload a Lebara SIM export (.xlsx) to add SIM Status and SIM Update columns">Upload SIM Export</button>' +
		'<button class="btn btn-default btn-sm fav-export" style="margin-left:6px">Export CSV</button>';
	el.headright.querySelector(".fav-refresh").addEventListener("click", refresh_snapshot);
	el.headright.querySelector(".fav-upload-sim").addEventListener("click", upload_sim_file);
	el.headright.querySelector(".fav-export").addEventListener("click", export_csv);

	// -------------------------------------------------------------- data

	function load() {
		load_summary();
		load_rows();
	}

	function load_summary() {
		frappe.call({ method: "app_apis.fleet_audit.get_summary" }).then(function (r) {
			summary = (r && r.message) || {};
			render_summary();
			render_chips();
		});
		frappe.call({ method: "app_apis.fleet_audit.get_filter_options" }).then(function (r) {
			options = (r && r.message) || {};
			if (last_res) render_rows(last_res);
		});
	}

	function load_rows() {
		frappe.call({
			method: "app_apis.fleet_audit.get_rows",
			args: Object.assign({}, filters, { start: start, limit: limit }),
		}).then(function (r) { render_rows((r && r.message) || {}); });
	}

	// ------------------------------------------------------------- summary

	function render_summary() {
		var s = summary || {};
		if (!s.has_run) {
			el.when.innerHTML = '<span class="dim">No audit has been run yet.</span>';
			return;
		}
		var secs = s.duration_seconds || 0;
		var sim = s.sim || {};
		el.when.innerHTML =
			"Last run " + esc(frappe.datetime.str_to_user(s.audited_at)) + " · " +
			num(s.rows) + " devices · " +
			(secs >= 60 ? Math.round(secs / 60) + " min" : secs + "s") +
			(sim.rows
				? " · SIM data: " + num(sim.rows) + " SIMs (" + num(sim.matched) + " matched)" +
				  (sim.last_import ? ", uploaded " + esc(frappe.datetime.str_to_user(sim.last_import)) : "")
				: " · No SIM file uploaded yet");

		var erp = s.erp || {}, im = s.im || {}, pilot = s.pilot || {};
		var c = s.cards || {};

		// Each tile answers ONE question. There is no "Need attention" total:
		// it used to sum seven unrelated problems -- 2,586 ERP records with no
		// device serial alongside 245 devices still tracking after deletion --
		// into a number nobody could act on.
		// Pilot's own device id is not always an IMEI -- the raw sweep total
		// (`pilot.devices`) includes 10-digit registration numbers and
		// SIM-length ids that can never be a real vehicle. These tiles use
		// the server's already-filtered "real IMEI" counts instead, so the
		// number here matches what Pilot's own admin panel would call the
		// fleet size, not the row count of one API call.
		el.tiles.innerHTML = [
			tile(erp.vehicles, "In ERPNext", null, null, "Total Customer Vehicle records."),
			tile(pilot.checked === false ? "—" : (c.pilot_wsl_devices || 0), "On Pilot (WSL)", { on_pilot_1: "1" }, null,
				"Real devices (15-digit IMEI) seen in the Pilot (WSL) estate sweep."),
			tile(pilot.checked === false ? "—" : (c.pilot_2_devices || 0), "On Pilot 2", { on_pilot_2: "1" }, null,
				"Real devices (15-digit IMEI) seen in the second Pilot estate sweep."),
			tile(im.checked === false ? "—" : im.devices, "On IM", null, null, "Devices IM is currently tracking."),
			tile(c.deleted_live, "Deleted but still live", { verdict: "Deleted but still live" }, "orange",
				"ERP marks it Deleted/Canceled, but it's still reporting on Pilot or IM."),
			tile(c.both_not_in_erp, "On IM + Pilot, not in ERPNext",
				{ erp_status: "Not in ERP", on_pilot: "1", on_im: "1" }, "purple",
				"Tracked by both platforms, and no Customer Vehicle mentions it at all."),
		].join("");

		el.tiles.querySelectorAll("[data-filters]").forEach(function (node) {
			node.addEventListener("click", function () {
				var f = JSON.parse(node.getAttribute("data-filters"));
				Object.keys(filters).forEach(function (k) { filters[k] = ""; });
				Object.assign(filters, f);
				start = 0;
				render_chips();
				load_rows();
				el.wrap.scrollIntoView({ behavior: "smooth", block: "nearest" });
			});
		});

		// Only shown when something is actually wrong with the run itself.
		var notes = [];
		if (pilot.skipped || pilot.checked === false) {
			notes.push("Pilot was not read in this run, so no Pilot findings were produced.");
		}
		if (im.skipped || im.checked === false) {
			notes.push("IM was not read in this run, so no IM findings were produced.");
		}
		el.notes.innerHTML = notes.length ? '<div class="fav-note">' + notes.join("<br>") + "</div>" : "";
	}

	// `filts` makes the tile a shortcut into the table below it; `tn` colours
	// the number so the two findings that cost money stand out.
	function tile(n, label, filts, tn, hint) {
		var clickable = filts
			? " data-filters='" + esc(JSON.stringify(filts)) + "' style=\"cursor:pointer\""
			: "";
		var colour = tn ? ' style="color:var(--' + tn + '-600,var(--text-color))"' : "";
		return '<div class="fav-tile"' + clickable + (hint ? ' title="' + esc(hint) + '"' : "") + '>' +
			'<div class="n"' + colour + '>' + (typeof n === "number" ? num(n) : esc(n)) + "</div>" +
			'<div class="l">' + esc(label) + "</div></div>";
	}

	// The chips ARE the filter. One click sets it, a second clears it.
	function render_chips() {
		var v = (summary || {}).verdicts || {};
		var chips = VERDICT_ORDER.filter(function (k) { return v[k]; }).map(function (k) {
			var on = filters.verdict === k ? " on" : "";
			return '<div class="fav-chip' + on + '" data-v="' + esc(k) + '">' +
				'<span class="fav-dot" style="background:var(--' + tone(k) + '-500,var(--text-muted))"></span>' +
				"<span>" + esc(k) + '</span><span class="c">' + num(v[k]) + "</span></div>";
		});
		el.chips.innerHTML = chips.join("");
		el.chips.querySelectorAll(".fav-chip").forEach(function (node) {
			node.addEventListener("click", function () {
				var val = node.getAttribute("data-v");
				filters.verdict = filters.verdict === val ? "" : val;
				start = 0;
				render_chips();
				load_rows();
			});
		});
	}

	// ---------------------------------------------------------------- rows

	// One filter cell per column. Text columns get a box, the rest a dropdown.
	function filter_row() {
		var o = options || {};
		function box(key, ph) {
			return '<th><input type="text" data-f="' + key + '" placeholder="' + esc(ph) + '" value="' +
				esc(filters[key]) + '"></th>';
		}
		function sel(key, opts, any) {
			var items = ['<option value="">' + esc(any) + "</option>"].concat(
				opts.map(function (o2) {
					var val = Array.isArray(o2) ? o2[0] : o2;
					var lbl = Array.isArray(o2) ? o2[1] : o2;
					var on = String(filters[key]) === String(val) ? " selected" : "";
					return '<option value="' + esc(val) + '"' + on + ">" + esc(lbl) + "</option>";
				})
			);
			return '<th><select data-f="' + key + '">' + items.join("") + "</select></th>";
		}
		// Two small native date pickers, "from" and "to" -- either can be left
		// blank (an open-ended range). Values are plain "YYYY-MM-DD"; the
		// server treats "to" as the END of that day, not the start of it.
		function daterange(key) {
			return '<th><div class="fav-daterange">' +
				'<input type="date" data-f="' + key + '_from" value="' + esc(filters[key + "_from"]) + '" title="From">' +
				'<input type="date" data-f="' + key + '_to" value="' + esc(filters[key + "_to"]) + '" title="To">' +
				"</div></th>";
		}
		// SIM No's search box. The "No SIM" toggle sits above the table, not
		// here -- when it is on, this box is cleared and disabled (searching a
		// SIM number while asking for the ones with none is contradictory).
		function sim_no_cell() {
			return '<th><input type="text" data-f="sim_msisdn" placeholder="SIM No" value="' +
				esc(filters.sim_msisdn) + '"' + (filters.no_sim ? " disabled" : "") + "></th>";
		}
		return '<tr class="fav-filters">' +
			box("imei", "IMEI") +
			box("vehicle", "Plate") +
			box("customer", "Customer") +
			sel("erp_status", o.erp_statuses || [], "Any") +
			sel("on_pilot_1", [["1", "Yes"], ["0", "No"]], "Any") +
			sel("on_pilot_2", [["1", "Yes"], ["0", "No"]], "Any") +
			sel("on_im", [["1", "Yes"], ["0", "No"]], "Any") +
			sel("sim_status", o.sim_statuses || [], "Any") +
			sel("verdict", o.verdicts || [], "Any") +
			sim_no_cell() +
			sel("sim_item", o.sim_items || [], "Any") +
			"<th></th>" + // Tickets -- no filter
			daterange("pilot_last_seen") +
			daterange("im_last_seen") +
			daterange("sim_last_seen") +
			"</tr>";
	}

	function bind_filter_row() {
		var apply = frappe.utils.debounce(function () {
			start = 0;
			render_chips();
			load_rows();
		}, 300);

		el.wrap.querySelectorAll("tr.fav-filters [data-f]").forEach(function (node) {
			var key = node.getAttribute("data-f");
			// A date picker fires "change" on pick, not "keyup" -- treated the
			// same as a select: act at once, no debounce.
			var immediate = node.tagName === "SELECT" || node.type === "date";
			var evt = immediate ? "change" : "keyup";
			node.addEventListener(evt, function () {
				filters[key] = node.value;
				if (immediate) {
					start = 0;
					render_chips();
					load_rows();
				} else {
					apply();
				}
			});
		});

	}

	// A click on a Pilot or IM cell asks that ONE platform, right now, for
	// this ONE device -- the same "check it live" a technician already does
	// from a ticket, just reachable from the audit row instead. Rebound after
	// every render, same as the filter row: `el.wrap.innerHTML` replaces the
	// nodes each time, so old listeners are simply gone with them.
	function bind_cell_clicks() {
		// The button carries only the IMEI; the rest of the row (customer,
		// last known Pilot/IM facts to fall back on) is looked up from the
		// last loaded page rather than re-encoded into the DOM.
		function row_for(imei) {
			return ((last_res || {}).rows || []).find(function (r) { return r.imei === imei; }) || { imei: imei };
		}
		el.wrap.querySelectorAll("[data-pilot]").forEach(function (node) {
			node.addEventListener("click", function () {
				var acc = parseInt(node.getAttribute("data-pilot-account"), 10) || 1;
				open_pilot_dialog(row_for(node.getAttribute("data-pilot")), acc);
			});
		});
		el.wrap.querySelectorAll("[data-im]").forEach(function (node) {
			node.addEventListener("click", function () {
				open_im_dialog(row_for(node.getAttribute("data-im")));
			});
		});
	}

	// A second, thin horizontal scrollbar ABOVE the table, mirroring the one
	// the browser already puts below it -- so scrolling sideways through 12
	// columns doesn't require scrolling all the way down to reach the real
	// bar first. `.onscroll =` (not addEventListener) is deliberate: the table
	// is rebuilt on every render, but `el.wrap` and `el.topscroll` themselves
	// are not, so addEventListener would stack a new listener on top of the
	// last one every time instead of replacing it.
	function sync_top_scroll() {
		var table = el.wrap.querySelector("table");
		if (!table || table.scrollWidth <= el.wrap.clientWidth) {
			el.topscroll.style.display = "none";
			return;
		}
		el.topscroll.style.display = "";
		el.topscroll.querySelector(".fav-topscroll-inner").style.width = table.scrollWidth + "px";

		var syncing = false;
		el.topscroll.onscroll = function () {
			if (syncing) return;
			syncing = true;
			el.wrap.scrollLeft = el.topscroll.scrollLeft;
			syncing = false;
		};
		el.wrap.onscroll = function () {
			if (syncing) return;
			syncing = true;
			el.topscroll.scrollLeft = el.wrap.scrollLeft;
			syncing = false;
		};
	}

	// ================================================================
	// Live device dialogs -- "Check Pilot" / "Check IM" for a Fleet Audit
	// row instead of a ticket. Same server methods' ticket-free siblings
	// (app_apis.connector.get_vehicle_live, app_apis.im_connector.get_vehicle_live),
	// same two-tier essential/"Show all" layout, same Leaflet map as the
	// xticket buttons -- a technician who has used one should not have to
	// learn the other.
	//
	// PILOT'S LIVE CHECK CAN FAIL EVEN WHEN THE ROW SAYS "ON PILOT": "on
	// Pilot" comes from the admin estate sweep (one login that sees every
	// sub-account's device list), but the LIVE read signs in as the
	// CUSTOMER's own Pilot account, and plenty of those have a stale or
	// wrong password. That is a real, common outcome on this deployment,
	// not a bug -- so a failure here falls back to what the last "Fetch
	// All" already recorded for this row instead of showing nothing.
	//
	// Deliberately NOT ported from the xticket scripts: the live ignition
	// flip-test (needs someone at the vehicle turning a key) and IM's 6h
	// track overlay. Both are ticket-workflow features; this is a fleet
	// list, and everything else -- checklist, tiles, sensor/port readings,
	// device fields, the map -- is kept.

	function fdecode(s) {
		var t = document.createElement("textarea");
		t.innerHTML = String(s === undefined || s === null ? "" : s);
		return t.value;
	}
	function fesc(v) {
		return frappe.utils.escape_html(fdecode(v));
	}
	function fdash(v) {
		return v === null || v === undefined || v === "" ? "&mdash;" : fesc(v);
	}
	function fago(sec) {
		if (sec === null || sec === undefined) return "unknown";
		sec = Math.max(0, Math.floor(sec));
		if (sec < 60) return sec + "s ago";
		if (sec < 3600) return Math.floor(sec / 60) + "m ago";
		if (sec < 86400) return Math.floor(sec / 3600) + "h ago";
		return Math.floor(sec / 86400) + "d ago";
	}
	function fepoch_text(epoch) {
		if (!epoch) return "";
		return frappe.datetime.str_to_user(
			frappe.datetime.convert_to_user_tz(
				moment.unix(Number(epoch)).utc().format("YYYY-MM-DD HH:mm:ss")
			)
		);
	}
	function fcompass(dir) {
		var n = Number(dir);
		if (dir === null || dir === undefined || dir === "" || Number.isNaN(n)) {
			return dir ? String(dir) : null;
		}
		var pts = ["N", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE", "S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW"];
		return pts[Math.round((n % 360) / 22.5) % 16];
	}
	function fduration(sec) {
		sec = Math.max(0, Math.floor(Number(sec) || 0));
		if (!sec) return "0s";
		var h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = sec % 60;
		if (h) return h + "h " + m + "m";
		if (m) return m + "m " + s + "s";
		return s + "s";
	}
	function fonoff(v) {
		if (v === true || v === 1 || v === "1") return "ON";
		if (v === false || v === 0 || v === "0") return "OFF";
		return "&mdash;";
	}

	function fsection(title, extra) {
		return '<div style="display:flex;align-items:center;gap:10px;margin:20px 0 10px">' +
			'<span style="font-size:11px;letter-spacing:.6px;text-transform:uppercase;color:var(--text-muted);' +
			'font-weight:600;white-space:nowrap">' + fesc(title) + "</span>" +
			(extra ? '<span style="font-size:11px;color:var(--text-muted);white-space:nowrap">' + fesc(extra) + "</span>" : "") +
			'<span style="flex:1;height:1px;background:var(--border-color)"></span></div>';
	}
	function ffield(label, value) {
		return '<div style="flex:1 1 145px;min-width:145px">' +
			'<div style="font-size:10px;letter-spacing:.5px;text-transform:uppercase;color:var(--text-muted)">' +
			fesc(label) + "</div>" +
			'<div style="margin-top:2px;word-break:break-word">' + value + "</div></div>";
	}
	function ftile(label, value, unit) {
		return '<div style="flex:1 1 90px;min-width:90px;padding:8px 10px;border:1px solid var(--border-color);' +
			'border-radius:var(--border-radius-md);background:var(--fg-color)">' +
			'<div style="font-size:10px;letter-spacing:.6px;text-transform:uppercase;color:var(--text-muted)">' +
			fesc(label) + "</div>" +
			'<div style="font-size:20px;font-weight:600;line-height:1.25;margin-top:2px">' + value +
			'<span style="font-size:11px;font-weight:400;color:var(--text-muted);margin-left:3px">' +
			fesc(unit || "") + "</span></div></div>";
	}
	function freading_tile(name, primary, secondary, foot) {
		return '<div style="flex:1 1 148px;min-width:148px;padding:9px 11px;border:1px solid var(--border-color);' +
			'border-radius:var(--border-radius-md);background:var(--fg-color)">' +
			'<div style="font-size:10px;letter-spacing:.5px;text-transform:uppercase;color:var(--text-muted);' +
			'white-space:nowrap;overflow:hidden;text-overflow:ellipsis">' + fesc(name) + "</div>" +
			'<div style="font-size:18px;font-weight:600;line-height:1.3;margin-top:2px">' + primary +
			(secondary ? '<span style="font-size:13px;font-weight:400;color:var(--text-muted)"> / ' + secondary + "</span>" : "") +
			"</div>" +
			(foot ? '<div style="font-size:10px;color:var(--text-muted);margin-top:1px">' + foot + "</div>" : "") +
			"</div>";
	}
	function fkv(rows) {
		var lines = rows.filter(function (r) { return r; });
		return '<table class="table table-borderless" style="margin:0;font-size:12px">' +
			lines.map(function (r) {
				return '<tr><td style="width:42%;padding:3px 0;color:var(--text-muted)">' + r[0] + "</td>" +
					'<td style="padding:3px 0;word-break:break-word">' + r[1] + "</td></tr>";
			}).join("") + "</table>";
	}
	function fbadge(text, tone) {
		return ' <span class="indicator-pill ' + tone + '" style="margin-left:6px">' + fesc(text) + "</span>";
	}
	function fheader(name, badges, subtitle, side) {
		return '<div style="display:flex;align-items:flex-start;justify-content:space-between;flex-wrap:wrap;gap:8px">' +
			"<div><div style=\"font-size:17px;font-weight:600\">" + fdash(name) + badges + "</div>" +
			'<div style="font-size:12px;color:var(--text-muted);margin-top:3px">' + subtitle + "</div></div>" +
			'<div class="text-muted" style="font-size:11px;text-align:right">' + side + "</div></div>";
	}
	function fdetail_dialog(title) {
		return new frappe.ui.Dialog({ title: title, size: "extra-large", fields: [{ fieldtype: "HTML", fieldname: "body" }] });
	}
	function fwire_toggle(dlg, cls) {
		dlg.$body.find("." + cls + "-toggle-all").on("click", function () {
			var $d = dlg.$body.find("." + cls + "-details");
			var showing = $d.is(":visible");
			$d.toggle(!showing);
			$(this).text(showing ? "Show all" : "Hide details");
		});
	}
	function fmap_links(loc) {
		return '<div style="margin-top:8px;display:flex;gap:6px;flex-wrap:wrap">' +
			'<a class="btn btn-xs btn-default" target="_blank" rel="noopener noreferrer" ' +
			'href="https://www.google.com/maps?q=' + encodeURIComponent(loc.lat + "," + loc.lon) + '">Google Maps</a>' +
			'<a class="btn btn-xs btn-default" target="_blank" rel="noopener noreferrer" ' +
			'href="https://www.openstreetmap.org/?mlat=' + encodeURIComponent(loc.lat) + "&mlon=" + encodeURIComponent(loc.lon) +
			"#map=16/" + encodeURIComponent(loc.lat) + "/" + encodeURIComponent(loc.lon) + '">OpenStreetMap</a>' +
			'<button class="btn btn-xs btn-default f-copy-coords">Copy Coordinates</button></div>';
	}

	// ERP context shared by both dialogs -- what a ticket section would show,
	// replaced because a Fleet Audit row is not a ticket.
	function ferp_section(row) {
		return fsection("ERPNext") + fkv([
			row.erp_vehicle
				? ["Vehicle", '<a href="/app/customer-vehicle/' + encodeURIComponent(row.erp_vehicle) + '">' +
					fesc(row.plate || row.erp_vehicle) + "</a>"]
				: ["Vehicle", "Not in ERPNext"],
			["Customer", row.customer
				? '<a href="/app/customer/' + encodeURIComponent(row.customer) + '">' + fesc(row.customer_name || row.customer) + "</a>"
				: fdash(row.customer_name)],
			["ERP status", fdash(row.erp_status)],
			["Finding", fdash(row.verdict)],
			row.erp_vehicle
				? ["Tickets", '<a href="/app/xticket?license_plate=' + encodeURIComponent(row.erp_vehicle) + '">Open tickets for this vehicle</a>']
				: null,
		]);
	}

	// ---------------------------------------------------------------- map
	//
	// Same approach as the xticket "Check Pilot"/"Check IM" map: frappe's own
	// bundled Leaflet (libs.bundle.js) and its own tile servers
	// (frappe.utils.map_defaults) -- no new dependency, no new external host.
	// Runs outside the shadow root (a Dialog is appended to document.body),
	// so jQuery here is the desk's own, not a risk to the block's own DOM.
	var fmap_instance = null;

	function render_device_map(map_id, loc, heading, popup_lines) {
		function init() {
			var el2 = document.getElementById(map_id);
			if (!el2 || el2._leaflet_id) return;
			try {
				fmap_instance = build_device_map(el2, loc, heading, popup_lines);
			} catch (e) {
				console.error("[fleet-audit] map failed to render", e);
				el2.innerHTML = '<div class="text-muted" style="padding:16px">Map could not be drawn: ' +
					fesc(String(e.message || e)) +
					'. <a target="_blank" rel="noopener noreferrer" href="https://www.openstreetmap.org/?mlat=' +
					encodeURIComponent(loc.lat) + "&mlon=" + encodeURIComponent(loc.lon) + '">Open map</a></div>';
			}
		}
		$(document).one("shown.bs.modal", init);
		setTimeout(init, 150);
		setTimeout(init, 700);
	}

	function build_device_map(el2, loc, heading, popup_lines) {
		if (typeof L === "undefined" || !L.map) throw new Error("Leaflet is not loaded");

		var defaults = (frappe.utils.map_defaults || {}).tiles || {};
		var map = L.map(el2, { scrollWheelZoom: false }).setView([loc.lat, loc.lon], 15);
		var street = L.tileLayer(
			(defaults.default_tile || {}).url || "https://tile.openstreetmap.org/{z}/{x}/{y}.png",
			(defaults.default_tile || {}).options || {}
		);
		var satellite = defaults.satellite_tile
			? L.tileLayer(defaults.satellite_tile.url, defaults.satellite_tile.options)
			: null;
		street.addTo(map);
		if (satellite) L.control.layers({ Street: street, Satellite: satellite }, {}).addTo(map);

		var h = Number(heading);
		var arrow = Number.isFinite(h)
			? '<div style="position:absolute;left:50%;top:50%;width:0;height:0;transform:translate(-50%,-50%) rotate(' + h + 'deg)">' +
			  '<div style="position:absolute;left:-6px;top:-24px;width:0;height:0;border-left:6px solid transparent;' +
			  'border-right:6px solid transparent;border-bottom:10px solid #2490ef"></div></div>'
			: "";
		var icon = L.divIcon({
			className: "", iconSize: [22, 22], iconAnchor: [11, 11],
			html: '<div style="position:relative;width:22px;height:22px">' + arrow +
				'<div style="position:absolute;inset:0;border-radius:50%;background:#2490ef;border:2px solid #fff;' +
				'box-shadow:0 0 0 1px rgba(0,0,0,.25)"></div></div>',
		});
		L.marker([loc.lat, loc.lon], { icon: icon }).addTo(map).bindPopup(popup_lines.join("<br>"));
		L.circle([loc.lat, loc.lon], { radius: 40, color: "#2490ef", weight: 1, opacity: 0.5, fillOpacity: 0.08 }).addTo(map);
		map.invalidateSize();
		setTimeout(function () { map.invalidateSize(); }, 300);
		return map;
	}

	// The app's frappe.throw arrives as `_server_messages`: a JSON string
	// holding an array of JSON strings, each {title, message, indicator}.
	function fserver_messages(r) {
		try {
			return JSON.parse(r._server_messages || "[]").map(function (m) {
				try { return JSON.parse(m); } catch (e) { return { message: String(m) }; }
			});
		} catch (e) {
			return [];
		}
	}

	// --------------------------------------------------------------- Pilot

	function pilot_all_sensors(d) {
		var all = (d.others || []).slice();
		(d.probes || []).forEach(function (p) {
			if (p.temperature) all.push(p.temperature);
			if (p.humidity) all.push(p.humidity);
		});
		return all;
	}
	function pilot_find_sensor(d, re) {
		return pilot_all_sensors(d).find(function (s) { return re.test(String(s.name || "")); });
	}

	function open_pilot_dialog(row, account) {
		// Same live check "Check Pilot" runs from a ticket: sign in as the
		// CUSTOMER's own Pilot account (read off Customer.email_pilot*) and ask
		// for this IMEI, retrying every account the customer has until one is
		// entitled to it -- not the admin/estate connection, which only sees
		// its own account and cannot see most rows here at all. `account`
		// picks WHICH Pilot estate's per-customer connection to use (1 = Pilot
		// (WSL), 2 = the second estate) -- set by which column's button was
		// pressed, so a Pilot 2 device is never tried against the WSL host.
		// The customer's own login is rejected more often than not on this
		// deployment (a stale password is common, especially once a customer's
		// ERP record is Deleted). That is shown immediately as a message with
		// its own "Fetch via Pilot Admin" button in `render_pilot_fallback` --
		// NOT triggered automatically here, on purpose: the admin estate sweep
		// has no single-device query, so it re-reads the whole ~24k-device
		// estate every time (up to 90s). Firing that on every failed check
		// would make browsing the table painfully slow; a button lets whoever
		// wants the slow, real answer ask for it deliberately.
		account = account || 1;
		frappe.call({
			method: "app_apis.connector.get_vehicle_live",
			args: { imei: row.imei, customer: row.customer || undefined, account: account },
			freeze: true,
			freeze_message: "Asking Pilot" + (account === 2 ? " (Pilot 2)" : " (WSL)") + "…",
			error_handlers: {
				ValidationError: function (r) { render_pilot_fallback(row, fserver_messages(r), account); },
			},
			callback: function (r) {
				if (!r || !r.message) { render_pilot_fallback(row, [], account); return; }
				render_pilot_essential(row, r.message);
			},
		});
	}

	function render_pilot_fallback(row, msgs, account) {
		account = account || 1;
		var estate = account === 2 ? "Pilot 2" : "Pilot (WSL)";
		var body = msgs.map(function (m) { return m.message || ""; }).join("\n\n");
		// The first "- someone@x (Customer.email_pilot) -> ..." line names the
		// account tried first; pre-fill the email box with it so a technician
		// only has to type the password they already know.
		var first_email = (body.match(/[-•]\s*([^\s()]+@[^\s()]+)/) || [])[1] || "";
		var seen = [row.on_pilot_1 ? "Pilot (WSL)" : null, row.on_pilot_2 ? "Pilot 2" : null].filter(Boolean);
		var known = seen.length
			? fkv([
				["Seen on", fesc(seen.join(", "))],
				["Vehicle No.", fdash(row.pilot_vehicle)],
				["Folder", fdash(row.pilot_folder)],
				["Account", fdash(row.pilot_account)],
				["Active", row.pilot_active ? "Yes" : "No"],
				["Last Seen", row.pilot_last_seen ? fesc(frappe.datetime.str_to_user(row.pilot_last_seen)) : "&mdash;"],
				["MSISDN", fdash(row.pilot_msisdn)],
			])
			: '<div class="text-muted">This device was not seen in the last Fetch All either.</div>';

		var dlg = fdetail_dialog("Pilot — " + row.imei);
		dlg.$body.html(
			'<div style="font-size:13px">' +
			'<div style="border-left:3px solid var(--orange-500,#e08e21);background:var(--card-bg);' +
			'border-radius:var(--border-radius-md);padding:9px 12px;margin-bottom:14px;font-size:12px">' +
			"<b>Could not reach Pilot live for this device.</b>" +
			(body ? '<div style="margin-top:6px;color:var(--text-muted);white-space:pre-wrap">' + fesc(body) + "</div>" : "") +

			// Try one login by hand. The email is pre-filled with the first
			// account the automatic try used; the password is whatever the
			// customer's Pilot login is NOW (often changed since what is on
			// file). Used for one request only -- never saved anywhere. The
			// automatic multi-account logic and the settings are untouched.
			'<div style="margin-top:10px;padding-top:9px;border-top:1px solid var(--border-color)">' +
			'<div style="color:var(--text-muted);font-size:11px;margin-bottom:6px">Try a ' + fesc(estate) +
			" login by hand — one request, nothing is saved:</div>" +
			'<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center">' +
			'<input type="text" class="pilot-cred-email" placeholder="email" value="' + fesc(first_email) +
			'" style="flex:1;min-width:170px;height:26px;font-size:12px;padding:2px 6px;border:1px solid var(--border-color);' +
			"border-radius:4px;background:var(--card-bg);color:var(--text-color)\">" +
			'<input type="password" class="pilot-cred-pass" placeholder="password" autocomplete="off" ' +
			'style="width:150px;height:26px;font-size:12px;padding:2px 6px;border:1px solid var(--border-color);' +
			"border-radius:4px;background:var(--card-bg);color:var(--text-color)\">" +
			'<button class="btn btn-xs btn-primary pilot-cred-check">Check</button>' +
			"</div>" +
			'<div class="pilot-cred-status" style="font-size:11px;margin-top:6px"></div>' +
			"</div>" +

			'<div style="margin-top:10px">' +
			'<button class="btn btn-xs btn-default pilot-admin-fallback">Fetch via Pilot Admin (slow — 30–90s)</button>' +
			'<span class="text-muted" style="font-size:11px;margin-left:6px">Re-sweeps the whole estate, since the admin ' +
			"connection has no way to ask for just this one device.</span></div>" +
			"</div>" +
			fsection("Last known (from the last Fetch All)") + known +
			ferp_section(row) + "</div>"
		);
		dlg.show();

		dlg.$body.find(".pilot-cred-check").on("click", function () {
			var email = (dlg.$body.find(".pilot-cred-email").val() || "").trim();
			var password = dlg.$body.find(".pilot-cred-pass").val() || "";
			var $status = dlg.$body.find(".pilot-cred-status");
			if (!email || !password) {
				$status.html('<span style="color:var(--red-600,#b4231b)">Enter both an email and a password.</span>');
				return;
			}
			$status.html('<span class="text-muted">Signing in to ' + fesc(estate) + "…</span>");
			frappe.call({
				method: "app_apis.connector.get_vehicle_live_with_credentials",
				args: { imei: row.imei, email: email, password: password, account: account },
				freeze: true,
				freeze_message: "Signing in to " + estate + " with the credentials you entered…",
				error_handlers: {
					ValidationError: function (r) {
						var m = fserver_messages(r).map(function (x) { return x.message || ""; }).join(" ");
						$status.html('<span style="color:var(--red-600,#b4231b);white-space:pre-wrap">' +
							fesc(/has no attribute/.test(m)
								? "Manual login check isn't available on this server yet."
								: (m || "That login did not work.")) + "</span>");
					},
				},
				callback: function (r) {
					if (!r || !r.message) {
						$status.html('<span style="color:var(--red-600,#b4231b)">Empty response.</span>');
						return;
					}
					dlg.hide();
					render_pilot_essential(row, r.message);
				},
			});
		});

		dlg.$body.find(".pilot-admin-fallback").on("click", function () {
			var $s = dlg.$body.find(".pilot-cred-status");
			frappe.call({
				method: "app_apis.pilot_admin.get_vehicle_live_admin",
				args: { imei: row.imei },
				freeze: true,
				freeze_message: "Re-sweeping Pilot's whole estate for this one device — this can take up to 90 seconds…",
				error_handlers: {
					ValidationError: function (r) {
						var m = fserver_messages(r).map(function (x) { return x.message || ""; }).join(" ");
						$s.html('<span style="color:var(--red-600,#b4231b);white-space:pre-wrap">' +
							fesc(/has no attribute/.test(m)
								? "The admin sweep isn't available on this server yet."
								: (m || "The admin sweep failed.")) + "</span>");
					},
				},
				callback: function (r) {
					if (!r || !r.message) return;
					dlg.hide();
					render_pilot_essential(row, r.message);
				},
			});
		});
	}

	function render_pilot_essential(row, d) {
		var st = d.state || {}, loc = d.location || {}, dev = d.device || {}, lu = d.last_update || {};
		var age = lu.age_seconds != null ? lu.age_seconds : (lu.epoch ? Math.max(0, Math.floor(Date.now() / 1000) - lu.epoch) : null);
		var is_stale = lu.is_stale != null ? lu.is_stale : (age == null || age > (d.stale_after_minutes || 15) * 60);
		var ign_reported = st.ignition !== null && st.ignition !== undefined && st.ignition !== "";
		var ign_on = st.ignition === 1 || st.ignition === "1" || st.ignition === true;
		var has_fix = loc.lat !== null && loc.lat !== undefined && loc.lon !== null && loc.lon !== undefined;
		var sats = parseInt(loc.sats, 10) || 0;
		var compass = fcompass(st.direction);
		var map_id = "fav-pilot-map-" + frappe.utils.get_random(8);

		var TONES = { ok: "var(--green-600,#16794c)", warn: "var(--orange-600,#b25000)", bad: "var(--red-600,#c0341d)", na: "var(--text-muted)" };
		var ICONS = { ok: "✓", warn: "!", bad: "✕", na: "–" };
		var WORDS = { ok: "OK", warn: "Check", bad: "Fail", na: "n/a" };
		function check_row(tone, label, value, hint, opts) {
			opts = opts || {};
			return '<tr style="border-top:1px solid var(--border-color)"' + (opts.id ? ' id="' + opts.id + '"' : "") + ">" +
				'<td class="fav-check-status" style="width:78px;padding:9px 0;vertical-align:top"><span style="display:inline-flex;align-items:center;' +
				'gap:5px;font-weight:600;font-size:11px;color:' + TONES[tone] + '"><span style="font-size:13px;line-height:1">' +
				ICONS[tone] + "</span>" + WORDS[tone] + "</span></td>" +
				'<td style="width:130px;padding:9px 0;vertical-align:top;color:var(--text-muted)">' + fesc(label) + "</td>" +
				'<td class="fav-check-value" style="padding:9px 0;vertical-align:top"><b>' + value + "</b>" +
				(hint ? '<div style="font-size:11px;color:var(--text-muted);margin-top:2px">' + hint + "</div>" : "") + "</td>" +
				'<td class="fav-check-action" style="padding:9px 0 9px 10px;vertical-align:top;text-align:right;white-space:nowrap">' +
				(opts.action || "") + "</td></tr>";
		}
		function chip(tone) {
			return '<span style="display:inline-flex;align-items:center;gap:5px;font-weight:600;font-size:11px;color:' + TONES[tone] + '">' +
				'<span style="font-size:13px;line-height:1">' + ICONS[tone] + "</span>" + WORDS[tone] + "</span>";
		}

		var gsm = pilot_find_sensor(d, /gsm|gprs|signal|network/i);
		var batt = pilot_find_sensor(d, /batt|volt|power|vbat|supply/i);
		var sensor_count = pilot_all_sensors(d).length;

		var checks = [
			check_row(is_stale ? "warn" : "ok", "Reporting", is_stale ? ("Last seen " + fesc(fago(age))) : ("Live, " + fesc(fago(age))),
				is_stale ? "No update for a while — check power and GSM antenna." : (lu.epoch ? ("Last fix " + fesc(fepoch_text(lu.epoch))) : "")),
			check_row(!has_fix ? "bad" : (sats && sats < 5 ? "warn" : "ok"), "GPS Fix",
				!has_fix ? "No position" : ((sats || "?") + " satellites · " + fesc(loc.lat + ", " + loc.lon)),
				!has_fix ? "Device has no GPS lock." : (sats && sats < 5 ? "Weak lock — reposition the antenna." : "")),
			check_row(ign_reported ? "ok" : "warn", "Ignition", ign_reported ? (ign_on ? "ON" : "OFF") : "Not reported",
				ign_reported ? "Reported value only — press Check Now to prove it follows the key." : "No ignition input — check the ACC wire.",
				{ id: "fav-pilot-ignition", action: ign_reported ? '<button class="btn btn-xs btn-default pilot-ign-test">Check Now</button>' : "" }),
			check_row(gsm ? "ok" : "na", "GSM Signal", gsm ? fesc(gsm.display || gsm.value) : "Not reported", gsm ? fesc(gsm.name) : ""),
			check_row(batt ? "ok" : "na", "Power", batt ? fesc(batt.display || batt.value) : "Not reported",
				batt ? "" : "This device does not report a battery sensor."),
			check_row(sensor_count ? "ok" : "warn", "Sensors", sensor_count + " reporting",
				sensor_count ? "Readings listed below." : "No sensor inputs are reporting."),
		].join("");

		var kpis = [
			ftile("Speed", st.speed == null ? "&mdash;" : fesc(st.speed), "km/h"),
			ftile("Heading", compass ? fesc(compass) : "&mdash;", Number.isFinite(Number(st.direction)) ? fesc(st.direction) + "°" : ""),
			ftile("Altitude", st.altitude == null ? "&mdash;" : fesc(st.altitude), "m"),
			ftile("Odometer", dev.current_mileage == null ? "&mdash;" : fesc(dev.current_mileage), "km"),
			ftile("Parked", fesc(fduration(st.parking)), ""),
		].join("");

		var probe_tiles = (d.probes || []).map(function (p) {
			var t = p.temperature || {}, h = p.humidity || {};
			return freading_tile(p.label, t.display ? fesc(t.display) : "&mdash;", h.display ? fesc(h.display) : "&mdash;",
				p.group ? fesc(p.group) : "");
		});
		var other_tiles = (d.others || []).map(function (o) {
			return freading_tile(o.name, o.display ? fesc(o.display) : (o.value != null ? fesc(o.value) : "&mdash;"), null, "");
		});
		var readings = probe_tiles.concat(other_tiles).join("");

		var device_fields = [
			ffield("IMEI", '<span style="font-family:monospace">' + fdash(dev.imei) + "</span>"),
			ffield("Vehicle No.", fdash(dev.name)),
			ffield("Model", fdash(dev.model)),
			ffield("Type", fdash(dev.type)),
			ffield("Folder", fdash(dev.folder)),
			ffield("Driver", fdash(dev.driver_name)),
		].join("");

		var essential =
			fheader(dev.name || row.plate,
				fbadge(is_stale ? "STALE" : "LIVE", is_stale ? "orange" : "green") + " · " + fesc(fago(age)),
				"IMEI <span style=\"font-family:monospace;color:var(--text-color)\">" + fdash(dev.imei) + "</span> · " + fdash(row.customer_name),
				"via " + fdash(d.account) + (d.estate ? " (" + fesc(d.estate) + ")" : "") + "<br>node " + fdash(d.node)) +
			fsection("Installation Checks") +
			'<table style="width:100%;font-size:12px;border-collapse:collapse">' + checks + "</table>" +
			fsection("Status") + '<div style="display:flex;gap:8px;flex-wrap:wrap">' + kpis + "</div>" +
			fsection("Sensor Readings") +
			(readings ? '<div style="display:flex;gap:8px;flex-wrap:wrap">' + readings + "</div>" : '<div class="text-muted">No sensors reported</div>') +
			fsection("Device") + '<div style="display:flex;gap:14px 18px;flex-wrap:wrap;font-size:12px">' + device_fields + "</div>" +
			fsection("Location") +
			(has_fix
				? '<div id="' + map_id + '" style="height:300px;border:1px solid var(--border-color);border-radius:var(--border-radius-md);' +
				  'overflow:hidden;background:var(--control-bg)"></div>' + fmap_links(loc)
				: '<div class="text-muted">No GPS fix reported</div>');

		var dlg = fdetail_dialog("Pilot — " + (dev.name || row.imei));
		dlg.$body.html(
			'<div style="font-size:13px">' + essential + ferp_section(row) +
			'<div style="margin:18px 0 0;padding-top:14px;border-top:1px solid var(--border-color);text-align:center">' +
			'<button class="btn btn-sm btn-default pilot-toggle-all">Show all</button></div>' +
			'<div class="pilot-details" style="display:none">' + build_pilot_details(d) + "</div></div>"
		);
		dlg.show();

		if (has_fix) {
			render_device_map(map_id, loc, st.direction, [
				"<b>" + fesc(dev.name || dev.imei) + "</b>",
				"Speed: " + fesc(st.speed) + " km/h",
				"Ignition: " + (ign_on ? "ON" : "OFF"),
				loc.lat + ", " + loc.lon,
			]);
		}
		fwire_toggle(dlg, "pilot");
		dlg.$body.find(".f-copy-coords").on("click", function () {
			frappe.utils.copy_to_clipboard(loc.lat + "," + loc.lon);
		});
		dlg.$body.find(".pilot-ign-test").on("click", function () {
			pilot_ignition_test(dlg, row, d, { chip: chip });
		});
	}

	// ---------------------------------------------------- Pilot ignition test
	//
	// Proves the ACC wire actually works, without anyone phoning the
	// technician. Reads the current state, asks for the OPPOSITE, then polls
	// Pilot every 5s for up to 5 minutes -- a flip observed is a pass, nothing
	// by the deadline is a fail. A disconnected ignition input reports a
	// permanent, plausible-looking OFF, which is why "the field has a value"
	// is not evidence of anything; only the transition is.
	//
	// Re-reads via the same customer-scoped `connector.get_vehicle_live` the
	// dialog itself used -- not `get_snapshot`, since there is no ticket here.

	var PILOT_IGN = { window_ms: 5 * 60 * 1000, poll_ms: 5000 };

	function pilot_ign_bool(v) {
		if (v === null || v === undefined || v === "") return null;
		if (v === 1 || v === "1" || v === true) return true;
		if (v === 0 || v === "0" || v === false) return false;
		var s = String(v).trim().toLowerCase();
		if (["on", "true", "yes"].indexOf(s) !== -1) return true;
		if (["off", "false", "no"].indexOf(s) !== -1) return false;
		return null;
	}
	function fmmss(ms) {
		var s = Math.max(0, Math.ceil(ms / 1000));
		return Math.floor(s / 60) + ":" + String(s % 60).padStart(2, "0");
	}

	function pilot_ignition_test(dlg, row, d, helpers) {
		var $row = dlg.$body.find("#fav-pilot-ignition");
		var $status = $row.find(".fav-check-status");
		var $value = $row.find(".fav-check-value");
		var $action = $row.find(".fav-check-action");

		var start_state = pilot_ign_bool((d.state || {}).ignition);
		if (start_state === null) {
			frappe.msgprint({
				title: "Ignition",
				message: "This device does not report an ignition value, so it cannot be tested.",
				indicator: "orange",
			});
			return;
		}

		var want = !start_state;
		var want_word = want ? "ON" : "OFF";
		var from_word = start_state ? "ON" : "OFF";
		var started_at = Date.now();
		var deadline = started_at + PILOT_IGN.window_ms;
		var polls = 0, in_flight = false, seen = start_state, timer = null;

		function stop() {
			if (timer) clearInterval(timer);
			timer = null;
			dlg.$wrapper.off("hidden.bs.modal", stop);
		}
		dlg.$wrapper.on("hidden.bs.modal", stop);

		function render() {
			var left = deadline - Date.now();
			var pct = Math.min(100, ((Date.now() - started_at) / PILOT_IGN.window_ms) * 100);
			$value.html(
				'<div style="font-size:14px;font-weight:600;color:var(--text-color)">Turn the ignition ' + want_word + ' now</div>' +
				'<div style="height:4px;border-radius:2px;background:var(--control-bg);margin:7px 0 5px;overflow:hidden">' +
				'<div style="height:100%;width:' + pct + '%;background:var(--blue-500,#2490ef);transition:width .9s linear"></div></div>' +
				'<div style="font-size:11px;color:var(--text-muted)">Watching Pilot · ' + fmmss(left) + ' left · ' + polls +
				' checks · currently reading <b>' + (seen === null ? "?" : (seen ? "ON" : "OFF")) + '</b></div>'
			);
			$action.html('<button class="btn btn-xs btn-default pilot-ign-stop">Stop</button>');
			$action.find(".pilot-ign-stop").on("click", function () { stop(); finish(null); });
		}

		function finish(result) {
			stop();
			var secs = Math.round((Date.now() - started_at) / 1000);
			if (result === true) {
				$status.html(helpers.chip("ok"));
				$value.html('<b style="color:var(--green-600,#16794c)">TRUE — ignition follows the key</b>' +
					'<div style="font-size:11px;color:var(--text-muted);margin-top:2px">Changed ' + from_word + ' → ' + want_word +
					' after ' + secs + 's (' + polls + ' checks). The ACC wire is working.</div>');
			} else if (result === false) {
				$status.html(helpers.chip("bad"));
				$value.html('<b style="color:var(--red-600,#c0341d)">FALSE — ignition did not change</b>' +
					'<div style="font-size:11px;color:var(--text-muted);margin-top:2px">Still ' + from_word + ' after ' +
					fmmss(PILOT_IGN.window_ms) + ' and ' + polls + ' checks. Check the ACC wire, the fuse, and that the key was actually turned.</div>');
			} else {
				$status.html(helpers.chip("warn"));
				$value.html('<b>Test stopped</b><div style="font-size:11px;color:var(--text-muted);margin-top:2px">Stopped after ' +
					secs + 's and ' + polls + ' checks — result unknown.</div>');
			}
			$action.html('<button class="btn btn-xs btn-default pilot-ign-test">Check Again</button>');
			$action.find(".pilot-ign-test").on("click", function () { pilot_ignition_test(dlg, row, d, helpers); });
		}

		function poll() {
			if (in_flight) return;
			in_flight = true;
			frappe.call({
				method: "app_apis.connector.get_vehicle_live",
				args: { imei: row.imei, customer: row.customer || undefined },
				callback: function (r) {
					in_flight = false;
					polls++;
					var msg = r && r.message;
					if (!msg) return;
					var cur = pilot_ign_bool((msg.state || {}).ignition);
					if (cur !== null) seen = cur;
					if (cur === want) { finish(true); return; }
					render();
				},
				error: function () { in_flight = false; polls++; },
			});
		}

		render();
		poll();
		timer = setInterval(function () {
			if (Date.now() >= deadline) { finish(false); return; }
			render();
			if ((Math.round((Date.now() - started_at) / 1000)) % (PILOT_IGN.poll_ms / 1000) === 0) poll();
		}, 1000);
	}

	function build_pilot_details(d) {
		var st = d.state || {}, loc = d.location || {}, dev = d.device || {}, diag = d.diagnostics || {};
		var compass = fcompass(st.direction);
		var now_epoch = diag.server_epoch || Math.floor(Date.now() / 1000);
		var has_coords = loc.lat !== null && loc.lat !== undefined && loc.lon !== null && loc.lon !== undefined;

		var probes = (d.probes || []).map(function (p) {
			var t = p.temperature || {}, h = p.humidity || {};
			return "<tr><td>" + fdash(p.index) + "</td><td>" + fdash(p.label) + "</td><td><b>" + fdash(t.display) +
				"</b></td><td><b>" + fdash(h.display) + '</b></td><td class="text-muted">' + fdash(p.group) + "</td></tr>";
		}).join("");
		var others = (d.others || []).map(function (o) {
			return "<tr><td>" + fdash(o.name) + "</td><td><b>" + fdash(o.display) + "</b></td>" +
				'<td class="text-muted">' + (o.value == null ? "&mdash;" : fesc(o.value)) + "</td>" +
				'<td class="text-muted">' + fdash(o.raw_value) + "</td>" +
				'<td class="text-muted">' + (o.ts ? fesc(fago(now_epoch - o.ts)) : "&mdash;") + "</td></tr>";
		}).join("");

		var rejected_html = (diag.rejected || []).length
			? '<div style="margin-top:6px"><div style="color:var(--text-muted)">Rejected accounts</div>' +
			  '<ul style="margin:4px 0 0 16px;padding:0">' +
			  diag.rejected.map(function (r) { return '<li style="margin-bottom:2px">' + fesc(r) + "</li>"; }).join("") +
			  "</ul></div>"
			: "";

		return '<div class="row"><div class="col-sm-6">' +
			fsection("Device") + fkv([
				["IMEI", fdash(dev.imei)], ["Vehicle No.", fdash(dev.name)], ["Folder", fdash(dev.folder)],
				["Type", fdash(dev.type)], ["Model", fdash(dev.model)], ["Agent ID", fdash(dev.agentid)],
				["Unique ID", fdash(dev.uniqid)], dev.vin ? ["VIN", fdash(dev.vin)] : null,
				["Driver", fdash(dev.driver_name)],
				["Odometer", dev.current_mileage == null ? "&mdash;" : fesc(dev.current_mileage) + " km"],
				dev.created_time ? ["Registered", fesc(fepoch_text(dev.created_time))] : null,
			]) + "</div><div class=\"col-sm-6\">" +
			fsection("State") + fkv([
				["Active", st.active ? "Yes" : "No"],
				["Ignition", (st.ignition === 1 || st.ignition === "1") ? "<b>ON</b>" : "OFF"],
				["Speed", st.speed == null ? "&mdash;" : fesc(st.speed) + " km/h"],
				["Heading", compass ? fesc(compass) : "&mdash;"],
				["Altitude", st.altitude == null ? "&mdash;" : fesc(st.altitude) + " m"],
				["Moving for", fesc(fduration(st.moving))],
				["Parked for", fesc(fduration(st.parking))],
				["Satellites", fdash(loc.sats)],
				["Coordinates", has_coords ? fesc(loc.lat + ", " + loc.lon) : "&mdash;"],
			]) + "</div></div>" +
			fsection("Probes") +
			(probes
				? '<table class="table table-bordered" style="margin:0;font-size:12px"><thead><tr><th>#</th><th>Label</th>' +
				  "<th>Temperature</th><th>Humidity</th><th>Group</th></tr></thead><tbody>" + probes + "</tbody></table>"
				: '<div class="text-muted">No probes reported</div>') +
			fsection("Other Sensors") +
			(others
				? '<table class="table table-bordered" style="margin:0;font-size:12px"><thead><tr><th>Sensor</th><th>Reading</th>' +
				  "<th>Value</th><th>Raw</th><th>Changed</th></tr></thead><tbody>" + others + "</tbody></table>"
				: '<div class="text-muted">No other sensors reported</div>') +
			fsection("Diagnostics") + '<div style="font-size:11px;color:var(--text-muted)">' + fkv([
				["Pilot Account", fdash(d.account) + " (" + fdash(d.account_source) + ")"],
				["Node", fdash(d.node)],
				["HTTP Status", fdash(diag.http_status)],
				["Round Trip", diag.elapsed_ms ? fesc(diag.elapsed_ms) + " ms" : "&mdash;"],
				["Accounts Tried", fdash(diag.accounts_tried)],
			]) + rejected_html + "</div>" +
			'<details style="margin-top:16px"><summary style="cursor:pointer;font-size:11px;letter-spacing:.5px;' +
			'text-transform:uppercase;color:var(--text-muted)">Raw Pilot payload</summary>' +
			'<pre style="margin-top:8px;max-height:280px;overflow:auto;font-size:11px;background:var(--control-bg);' +
			'padding:10px;border-radius:var(--border-radius-md)">' +
			frappe.utils.escape_html(JSON.stringify(d.raw || {}, null, 2)) + "</pre></details>";
	}

	// ----------------------------------------------------------------- IM

	function im_group_readings(list) {
		var groups = {};
		(list || []).forEach(function (o) {
			var g = o.group || "Other";
			(groups[g] = groups[g] || []).push(o);
		});
		return groups;
	}

	function open_im_dialog(row) {
		frappe.call({
			method: "app_apis.im_connector.get_vehicle_live",
			args: { imei: row.imei },
			freeze: true,
			freeze_message: "Asking IM…",
			error_handlers: {
				ValidationError: function (r) { render_im_fallback(row, fserver_messages(r)); },
			},
			callback: function (r) {
				if (!r || !r.message) { render_im_fallback(row, []); return; }
				render_im_essential(row, r.message);
			},
		});
	}

	function render_im_fallback(row, msgs) {
		var body = msgs.map(function (m) { return m.message || ""; }).join("\n\n");
		var known = row.on_im
			? fkv([
				["Vehicle No.", fdash(row.im_vehicle)],
				["Company", fdash(row.im_company)],
				["Status", fdash(row.im_status)],
				["Last Seen", row.im_last_seen ? fesc(frappe.datetime.str_to_user(row.im_last_seen)) : "&mdash;"],
			])
			: '<div class="text-muted">This device was not seen in the last Fetch All either.</div>';

		var dlg = fdetail_dialog("IM — " + row.imei);
		dlg.$body.html(
			'<div style="font-size:13px">' +
			'<div style="border-left:3px solid var(--orange-500,#e08e21);background:var(--card-bg);' +
			'border-radius:var(--border-radius-md);padding:9px 12px;margin-bottom:14px;font-size:12px">' +
			"<b>Could not reach IM live for this device.</b>" +
			(body ? '<div style="margin-top:6px;color:var(--text-muted);white-space:pre-wrap">' + fesc(body) + "</div>" : "") +
			"</div>" +
			fsection("Last known (from the last Fetch All)") + known +
			ferp_section(row) + "</div>"
		);
		dlg.show();
	}

	function render_im_essential(row, d) {
		var st = d.state || {}, loc = d.location || {}, dev = d.device || {}, lu = d.last_update || {};
		var readings = d.readings || [], unwired = d.unwired || [];
		var age = lu.age_seconds != null ? lu.age_seconds : (lu.epoch ? Math.max(0, Math.floor(Date.now() / 1000) - lu.epoch) : null);
		var is_stale = lu.is_stale != null ? lu.is_stale : (age == null || age > (d.stale_after_minutes || 15) * 60);
		var ign_reported = st.ignition !== null && st.ignition !== undefined;
		var has_fix = loc.lat !== null && loc.lat !== undefined && loc.lon !== null && loc.lon !== undefined;
		var compass = fcompass(st.direction);
		var map_id = "fav-im-map-" + frappe.utils.get_random(8);

		var TONES = { ok: "var(--green-600,#16794c)", warn: "var(--orange-600,#b25000)", bad: "var(--red-600,#c0341d)", na: "var(--text-muted)" };
		var ICONS = { ok: "✓", warn: "!", bad: "✕", na: "–" };
		var WORDS = { ok: "OK", warn: "Check", bad: "Fail", na: "n/a" };
		function check_row(tone, label, value, hint, opts) {
			opts = opts || {};
			return '<tr style="border-top:1px solid var(--border-color)"' + (opts.id ? ' id="' + opts.id + '"' : "") + ">" +
				'<td class="fav-check-status" style="width:78px;padding:9px 0;vertical-align:top"><span style="display:inline-flex;align-items:center;' +
				'gap:5px;font-weight:600;font-size:11px;color:' + TONES[tone] + '"><span style="font-size:13px;line-height:1">' +
				ICONS[tone] + "</span>" + WORDS[tone] + "</span></td>" +
				'<td style="width:130px;padding:9px 0;vertical-align:top;color:var(--text-muted)">' + fesc(label) + "</td>" +
				'<td class="fav-check-value" style="padding:9px 0;vertical-align:top"><b>' + value + "</b>" +
				(hint ? '<div style="font-size:11px;color:var(--text-muted);margin-top:2px">' + hint + "</div>" : "") + "</td>" +
				'<td class="fav-check-action" style="padding:9px 0 9px 10px;vertical-align:top;text-align:right;white-space:nowrap">' +
				(opts.action || "") + "</td></tr>";
		}
		function chip(tone) {
			return '<span style="display:inline-flex;align-items:center;gap:5px;font-weight:600;font-size:11px;color:' + TONES[tone] + '">' +
				'<span style="font-size:13px;line-height:1">' + ICONS[tone] + "</span>" + WORDS[tone] + "</span>";
		}

		var volt = st.external_volt, batt = st.battery_percentage;
		var checks = [
			check_row(is_stale ? "warn" : "ok", "Reporting", is_stale ? ("Last seen " + fesc(fago(age))) : ("Live, " + fesc(fago(age))), ""),
			check_row(st.status_text == null ? "na" : (String(st.status_text).toUpperCase() === "ACTIVE" ? "ok" : "warn"),
				"Platform", fdash(st.status_text), "IM subscription / device state for this vehicle."),
			check_row(!has_fix ? "bad" : (st.gps === false ? "warn" : "ok"), "GPS Fix",
				!has_fix ? "No position" : fesc(loc.lat + ", " + loc.lon), loc.address ? fesc(loc.address) : ""),
			check_row("warn", "Ignition", ign_reported ? fonoff(st.ignition) : "Not reported",
				ign_reported ? "Reported value only — not yet tested. Press Check Now at the vehicle." : "No ignition input — check the ACC wire.",
				{ id: "fav-im-ignition", action: ign_reported ? '<button class="btn btn-xs btn-default im-ign-test">Check Now</button>' : "" }),
			check_row(
				volt == null ? (st.power == null ? "na" : (st.power ? "ok" : "bad")) : (volt < 11 ? "bad" : (volt < 12 ? "warn" : "ok")),
				"Power", volt == null ? fonoff(st.power) : fesc(volt) + " V", ""),
			check_row(readings.length ? "ok" : "warn", "Ports", readings.length + " reporting",
				unwired.length ? ("Not wired: " + unwired.map(function (o) { return fdecode(o.name); }).join(", ")) : "Every documented port is reporting."),
		].join("");

		var kpis = [
			ftile("Speed", st.speed == null ? "&mdash;" : fesc(st.speed), "km/h"),
			ftile("Heading", compass ? fesc(compass) : "&mdash;", Number.isFinite(Number(st.direction)) ? fesc(st.direction) + "°" : ""),
			ftile("Temperature", st.temperature == null ? "&mdash;" : fesc(st.temperature), "°C"),
			ftile("Humidity", st.humidity == null ? "&mdash;" : fesc(st.humidity), "%RH"),
			ftile("Battery", batt == null ? "&mdash;" : fesc(batt), "%"),
			ftile("Odometer", dev.current_mileage == null ? "&mdash;" : fesc(dev.current_mileage), "km"),
		].join("");

		var grouped = im_group_readings(readings);
		var reading_html = Object.keys(grouped).map(function (g) {
			var tiles = grouped[g].map(function (o) {
				return freading_tile(o.name, o.display ? fesc(o.display) : "&mdash;", null, "");
			}).join("");
			return '<div style="margin-bottom:10px"><div style="font-size:10px;letter-spacing:.5px;text-transform:uppercase;' +
				'color:var(--text-muted);margin-bottom:5px">' + fesc(g) + "</div>" +
				'<div style="display:flex;gap:8px;flex-wrap:wrap">' + tiles + "</div></div>";
		}).join("");

		var device_fields = [
			ffield("IMEI", '<span style="font-family:monospace">' + fdash(dev.imei) + "</span>"),
			ffield("Vehicle No.", fdash(dev.name)),
			ffield("Vehicle Name", fdash(dev.vehicle_name)),
			ffield("Model", fdash(dev.model)),
			ffield("Company", fdash(dev.company)),
			ffield("Branch", fdash(dev.folder)),
			ffield("Driver", fdash(dev.driver_name)),
		].join("");

		var essential =
			fheader(dev.name || dev.vehicle_name || row.plate,
				fbadge(is_stale ? "STALE" : "LIVE", is_stale ? "orange" : "green") + " · " + fesc(fago(age)) +
					(d.diagnostics && d.diagnostics.throttled ? fbadge("CACHED", "orange") : ""),
				"IMEI <span style=\"font-family:monospace;color:var(--text-color)\">" + fdash(dev.imei) + "</span> · " + fdash(row.customer_name),
				"via " + fdash(d.account) + "<br>project " + fdash(d.project_id)) +
			fsection("Installation Checks") +
			'<table style="width:100%;font-size:12px;border-collapse:collapse">' + checks + "</table>" +
			fsection("Status") + '<div style="display:flex;gap:8px;flex-wrap:wrap">' + kpis + "</div>" +
			fsection("Port Readings", unwired.length ? (unwired.length + " port(s) not wired") : "") +
			(reading_html || '<div class="text-muted">No ports are reporting</div>') +
			fsection("Device") + '<div style="display:flex;gap:14px 18px;flex-wrap:wrap;font-size:12px">' + device_fields + "</div>" +
			fsection("Location") +
			(has_fix
				? '<div id="' + map_id + '" style="height:300px;border:1px solid var(--border-color);border-radius:var(--border-radius-md);' +
				  'overflow:hidden;background:var(--control-bg)"></div>' + fmap_links(loc)
				: '<div class="text-muted">No GPS fix reported</div>');

		var dlg = fdetail_dialog("IM — " + (dev.name || dev.vehicle_name || row.imei));
		dlg.$body.html(
			'<div style="font-size:13px">' + essential + ferp_section(row) +
			'<div style="margin:18px 0 0;padding-top:14px;border-top:1px solid var(--border-color);text-align:center">' +
			'<button class="btn btn-sm btn-default im-toggle-all">Show all</button></div>' +
			'<div class="im-details" style="display:none">' + build_im_details(d) + "</div></div>"
		);
		dlg.show();

		if (has_fix) {
			render_device_map(map_id, loc, st.direction, [
				"<b>" + fesc(dev.name || dev.vehicle_name || dev.imei) + "</b>",
				"Speed: " + fesc(st.speed) + " km/h",
				"Ignition: " + (st.ignition === true ? "ON" : "OFF"),
				loc.lat + ", " + loc.lon,
			]);
		}
		fwire_toggle(dlg, "im");
		dlg.$body.find(".f-copy-coords").on("click", function () {
			frappe.utils.copy_to_clipboard(loc.lat + "," + loc.lon);
		});
		dlg.$body.find(".im-ign-test").on("click", function () {
			im_ignition_test(dlg, row, d, { chip: chip });
		});
	}

	// ------------------------------------------------------- IM ignition test
	//
	// Same proof as Pilot's, but THE POLL RATE IS NOT A CONSTANT: IM allows
	// roughly one live call per one-to-two minutes per account, so the
	// interval comes from the snapshot (`poll_interval_seconds`, from IM
	// Settings) and the window is minutes long rather than Pilot's five --
	// hard-coding 5s would just collect rate-limit errors and prove nothing.

	function im_ign_bool(v) {
		if (v === true) return true;
		if (v === false) return false;
		if (v === null || v === undefined || v === "") return null;
		var s = String(v).trim().toLowerCase();
		if (["on", "1", "true", "yes"].indexOf(s) !== -1) return true;
		if (["off", "0", "false", "no"].indexOf(s) !== -1) return false;
		return null;
	}

	function im_ignition_test(dlg, row, d, helpers) {
		var $row = dlg.$body.find("#fav-im-ignition");
		var $status = $row.find(".fav-check-status");
		var $value = $row.find(".fav-check-value");
		var $action = $row.find(".fav-check-action");

		var start_state = im_ign_bool((d.state || {}).ignition);
		if (start_state === null) {
			frappe.msgprint({
				title: "Ignition",
				message: "This device does not report an ignition value, so it cannot be tested.",
				indicator: "orange",
			});
			return;
		}

		var poll_ms = Math.max(30, Number(d.poll_interval_seconds) || 90) * 1000;
		var window_ms = Math.max(1, Number(d.ignition_window_minutes) || 10) * 60 * 1000;
		var want = !start_state;
		var want_word = want ? "ON" : "OFF";
		var from_word = start_state ? "ON" : "OFF";
		var started_at = Date.now();
		var deadline = started_at + window_ms;
		var polls = 0, in_flight = false, seen = start_state, next_poll_at = Date.now() + poll_ms, timer = null;

		function stop() {
			if (timer) clearInterval(timer);
			timer = null;
			dlg.$wrapper.off("hidden.bs.modal", stop);
		}
		dlg.$wrapper.on("hidden.bs.modal", stop);

		function seen_word() { return seen === null ? "unknown" : (seen ? "ON" : "OFF"); }

		function render() {
			var left = deadline - Date.now();
			var pct = Math.min(100, ((Date.now() - started_at) / window_ms) * 100);
			var next_in = Math.max(0, Math.ceil((next_poll_at - Date.now()) / 1000));
			$value.html(
				'<div style="font-size:14px;font-weight:600;color:var(--text-color)">Turn the ignition ' + want_word + ' now</div>' +
				'<div style="height:4px;border-radius:2px;background:var(--control-bg);margin:7px 0 5px;overflow:hidden">' +
				'<div style="height:100%;width:' + pct + '%;background:var(--blue-500,#2490ef);transition:width .9s linear"></div></div>' +
				'<div style="font-size:11px;color:var(--text-muted)">Watching IM · ' + fmmss(left) + ' left · ' + polls +
				' checks · next in ' + next_in + 's · currently reading <b>' + seen_word() + '</b></div>' +
				'<div style="font-size:10px;color:var(--text-muted);margin-top:2px">IM allows about one live call per minute, ' +
				'so this re-reads every ' + Math.round(poll_ms / 1000) + 's.</div>'
			);
			$action.html('<button class="btn btn-xs btn-default im-ign-stop">Stop</button>');
			$action.find(".im-ign-stop").on("click", function () { stop(); finish(null); });
		}

		function state_tail() {
			return '<div style="font-size:11px;margin-top:5px;padding-top:5px;border-top:1px dashed var(--border-color)">' +
				'State received from IM: <b>' + seen_word() + '</b> <span style="color:var(--text-muted)">· ' + polls + ' checks</span></div>';
		}

		function finish(result) {
			stop();
			var secs = Math.round((Date.now() - started_at) / 1000);
			if (result === true) {
				$status.html(helpers.chip("ok"));
				$value.html('<b style="color:var(--green-600,#16794c)">TRUE — ignition follows the key</b>' +
					'<div style="font-size:11px;color:var(--text-muted);margin-top:2px">Changed ' + from_word + ' → ' + want_word +
					' after ' + secs + 's (' + polls + ' checks). The ACC wire is working.</div>' + state_tail());
			} else if (result === false) {
				$status.html(helpers.chip("bad"));
				$value.html('<b style="color:var(--red-600,#c0341d)">FALSE — ignition did not change</b>' +
					'<div style="font-size:11px;color:var(--text-muted);margin-top:2px">Still ' + from_word + ' after ' +
					fmmss(window_ms) + ' and ' + polls + ' checks. Check the ACC wire, the fuse, and that the key was actually turned.</div>' + state_tail());
			} else {
				$status.html(helpers.chip("warn"));
				$value.html('<b>Test stopped</b><div style="font-size:11px;color:var(--text-muted);margin-top:2px">Stopped after ' +
					secs + 's and ' + polls + ' checks — result unknown.</div>' + state_tail());
			}
			$action.html('<button class="btn btn-xs btn-default im-ign-test">Check Again</button>');
			$action.find(".im-ign-test").on("click", function () { im_ignition_test(dlg, row, d, helpers); });
		}

		function poll() {
			if (in_flight) return;
			in_flight = true;
			next_poll_at = Date.now() + poll_ms;
			frappe.call({
				method: "app_apis.im_connector.get_vehicle_live",
				args: { imei: row.imei },
				callback: function (r) {
					in_flight = false;
					polls++;
					var msg = r && r.message;
					if (!msg) return;
					var cur = im_ign_bool((msg.state || {}).ignition);
					if (cur !== null) seen = cur;
					if (cur === want) { finish(true); return; }
					render();
				},
				error: function () { in_flight = false; polls++; },
			});
		}

		render();
		poll();
		timer = setInterval(function () {
			if (Date.now() >= deadline) { finish(false); return; }
			render();
			if (Date.now() >= next_poll_at) poll();
		}, 1000);
	}

	function build_im_details(d) {
		var st = d.state || {}, loc = d.location || {}, dev = d.device || {}, diag = d.diagnostics || {};
		var readings = (d.readings || []).concat(d.unwired || []);
		var compass = fcompass(st.direction);
		var volt = st.external_volt, batt = st.battery_percentage;
		var has_coords = loc.lat !== null && loc.lat !== undefined && loc.lon !== null && loc.lon !== undefined;

		var port_rows = readings.map(function (o) {
			return "<tr><td>" + fdash(o.name) + "</td><td><b>" + (o.display ? fesc(o.display) : "&mdash;") + "</b></td>" +
				'<td class="text-muted">' + (o.value == null ? "&mdash;" : fesc(o.value)) + "</td>" +
				'<td class="text-muted">' + fdash(o.group) + "</td>" +
				'<td class="text-muted">' + (o.reported ? "yes" : "not wired") + "</td></tr>";
		}).join("");

		return '<div class="row"><div class="col-sm-6">' +
			fsection("Device") + fkv([
				["IMEI", fdash(dev.imei)], ["Vehicle No.", fdash(dev.name)], ["Vehicle Name", fdash(dev.vehicle_name)],
				["Company", fdash(dev.company)], ["Branch", fdash(dev.folder)], ["Type", fdash(dev.type)],
				["Device Model", fdash(dev.model)], ["Driver", fdash(dev.driver_name)],
				["Odometer", dev.current_mileage == null ? "&mdash;" : fesc(dev.current_mileage) + " km"],
			]) + "</div><div class=\"col-sm-6\">" +
			fsection("State") + fkv([
				["Platform Status", fdash(st.status_text)],
				["Ignition", st.ignition === true ? "<b>ON</b>" : fonoff(st.ignition)],
				["Speed", st.speed == null ? "&mdash;" : fesc(st.speed) + " km/h"],
				["Heading", compass ? fesc(compass) : "&mdash;"],
				["GPS Port", fonoff(st.gps)], ["Power Port", fonoff(st.power)],
				["SOS", fonoff(st.sos)], ["A/C", fonoff(st.ac)], ["Immobiliser", fonoff(st.immobilised)],
				["External Voltage", volt == null ? "&mdash;" : fesc(volt) + " V"],
				["Battery", batt == null ? "&mdash;" : fesc(batt) + " %"],
				["Coordinates", has_coords ? fesc(loc.lat + ", " + loc.lon) : "&mdash;"],
				["Address", fdash(loc.address)],
			]) + "</div></div>" +
			fsection("All Ports") +
			(port_rows
				? '<table class="table table-bordered" style="margin:0;font-size:12px"><thead><tr><th>Port</th><th>Reading</th>' +
				  "<th>Value</th><th>Group</th><th>Wired</th></tr></thead><tbody>" + port_rows + "</tbody></table>"
				: '<div class="text-muted">IM reported no ports</div>') +
			fsection("Diagnostics") + '<div style="font-size:11px;color:var(--text-muted)">' + fkv([
				["IM Account", fdash(d.account)], ["Project ID", fdash(d.project_id)],
				["HTTP Status", fdash(diag.http_status)],
				["Round Trip", diag.elapsed_ms ? fesc(diag.elapsed_ms) + " ms" : "&mdash;"],
				["Served From Cache", diag.cached ? ("yes (" + fesc(fago(diag.cache_age)) + ")") : "no"],
				["Rate Limited", diag.throttled ? ("<b>yes</b> — " + fdash(diag.throttle_msg)) : "no"],
			]) + "</div>" +
			'<details style="margin-top:16px"><summary style="cursor:pointer;font-size:11px;letter-spacing:.5px;' +
			'text-transform:uppercase;color:var(--text-muted)">Raw IM payload</summary>' +
			'<pre style="margin-top:8px;max-height:280px;overflow:auto;font-size:11px;background:var(--control-bg);' +
			'padding:10px;border-radius:var(--border-radius-md)">' +
			frappe.utils.escape_html(JSON.stringify(d.raw || {}, null, 2)) + "</pre></details>";
	}

	function render_rows(res) {
		last_res = res;
		var rows = res.rows || [];
		var total = res.total || 0;
		var active = Object.keys(filters).filter(function (k) { return filters[k] !== ""; });
		var filtered = active.length > 0;

		// The count, above the table, always -- and it names what is filtering.
		var LABEL = {
			imei: "IMEI", vehicle: "Vehicle", customer: "Customer",
			erp_status: "ERP status", on_pilot: "Pilot",
			on_pilot_1: "Pilot (WSL)", on_pilot_2: "Pilot 2", on_im: "IM",
			sim_status: "SIM status", sim_msisdn: "SIM No", no_sim: "No SIM", sim_item: "SIM Type", verdict: "Finding",
			pilot_last_seen_from: "Pilot update from", pilot_last_seen_to: "Pilot update to",
			im_last_seen_from: "IM update from", im_last_seen_to: "IM update to",
			sim_last_seen_from: "SIM update from", sim_last_seen_to: "SIM update to",
		};
		var YESNO = { "1": "Yes", "0": "No" };
		var YESNO_KEYS = { on_pilot: 1, on_pilot_1: 1, on_pilot_2: 1, on_im: 1, no_sim: 1 };
		var parts = active.map(function (k) {
			var v = filters[k];
			var shown = YESNO_KEYS[k] ? (YESNO[v] || v) : v;
			return LABEL[k] + ": " + esc(shown);
		});
		el.count.innerHTML = filtered
			? "<b>" + num(total) + "</b> of " + num((summary || {}).rows || 0) +
			  ' <span class="dim">· ' + parts.join(" · ") + "</span>"
			: "<b>" + num(total) + "</b> devices";
		el.clear.style.display = filtered ? "" : "none";
		// Keep the standalone toggle honest whatever changed the filter (tile
		// click, Clear filters, this box itself).
		if (el.nosim) el.nosim.checked = filters.no_sim === "1";

		// No early return on an empty result: the header carries the filter
		// controls, so blanking the table would take away the only thing that
		// could undo a filter matching nothing.
		var empty = (total === 0 && !filtered)
			? "The snapshot is empty. Press Refresh."
			: "Nothing matches these filters.";

		var dash = '<span class="dim">—</span>';
		// The Yes/No/Not-read check as a round button rather than plain text --
		// and, wherever there is a real IMEI to ask about, a LIVE button: press
		// it and it fetches this one device from the platform right now, the
		// same "Check Pilot" / "Check IM" a technician already has on a ticket.
		function flag_button(on, checked, kind, label, imei, pilotAccount) {
			var tone_cls, symbol, title;
			if (checked === 0 || checked === false) {
				tone_cls = "gray"; symbol = "–"; title = "Not read in this run";
			} else if (on) {
				tone_cls = "green"; symbol = "✓"; title = "On " + label;
			} else {
				tone_cls = "red"; symbol = "✗"; title = "Not on " + label;
			}

			var can_check = /^\d{15}$/.test(imei || "");
			var attrs = "";
			if (can_check) {
				title = "Click to check " + (kind === "pilot" ? "Pilot" : "IM") + " live — currently " + label + ": " + title;
				attrs = kind === "pilot"
					? ' data-pilot="' + esc(imei) + '" data-pilot-account="' + (pilotAccount || 1) + '"'
					: ' data-im="' + esc(imei) + '"';
			} else {
				attrs = " disabled";
			}

			return '<button type="button" class="fav-round fav-round-' + tone_cls +
				(can_check ? " fav-round-live" : "") + '"' + attrs + ' title="' + esc(title) + '">' +
				symbol + "</button>";
		}
		function when(v) {
			return v ? esc(frappe.datetime.str_to_user(v)) : dash;
		}

		var body = rows.map(function (r) {
			var t = tone(r.verdict);

			// The IMEI is a Serial No in the ERP -- but only for devices the ERP
			// actually knows. A Pilot- or IM-only device has no Serial No record,
			// so linking it would send people to a 404.
			var imei_cell = !r.imei
				? dash
				: r.erp_vehicle
				? '<a href="/app/serial-no/' + encodeURIComponent(r.imei) + '">' + esc(r.imei) + "</a>"
				: '<span title="Not in ERPNext, so there is no Serial No record">' + esc(r.imei) + "</span>";

			// xticket.license_plate is a Link to Customer Vehicle, so the ticket
			// list filters on the vehicle's name -- not on the printed plate,
			// which is spelled several ways across these systems.
			var tickets_cell = r.erp_vehicle
				? '<a class="btn btn-default btn-xs" title="Tickets for this vehicle" href="/app/xticket?license_plate=' +
				  encodeURIComponent(r.erp_vehicle) + '">Tickets</a>'
				: dash;

			var sim_no = (r.sim_msisdn || "").trim();
			// The SIM's carrier, straight off the ERP (Customer Vehicle SIM
			// Serial -> Item name): "Lebara SIM", "STC SIM", ...
			var sim_type_cell = r.sim_item ? esc(r.sim_item) : dash;

			return "<tr>" +
				'<td class="mono">' + imei_cell + "</td>" +
				"<td>" + (r.erp_vehicle
					? '<a href="/app/customer-vehicle/' + encodeURIComponent(r.erp_vehicle) + '">' +
					  esc(r.plate || r.erp_vehicle) + "</a>"
					: dash) + "</td>" +
				"<td>" + (r.customer
					? '<a href="/app/customer/' + encodeURIComponent(r.customer) + '">' +
					  esc(r.customer_name || r.customer) + "</a>"
					: (r.customer_name ? esc(r.customer_name) : dash)) + "</td>" +
				"<td>" + esc(r.erp_status || "") + "</td>" +
				'<td class="c">' + flag_button(r.on_pilot_1, r.pilot_checked, "pilot", "Pilot (WSL)", r.imei, 1) + "</td>" +
				'<td class="c">' + flag_button(r.on_pilot_2, r.pilot_checked, "pilot", "Pilot 2", r.imei, 2) + "</td>" +
				'<td class="c">' + flag_button(r.on_im, r.im_checked, "im", "IM", r.imei) + "</td>" +
				"<td>" + (r.sim_status ? esc(r.sim_status) : dash) + "</td>" +
				'<td><span class="pill" title="' + esc(r.issues || r.verdict) + '" style="background:var(--' +
					t + "-100,var(--control-bg));color:var(--" + t + '-600,var(--text-color))">' +
					esc(r.verdict) + "</span></td>" +
				"<td>" + (sim_no ? esc(sim_no) : dash) + "</td>" +
				"<td>" + sim_type_cell + "</td>" +
				'<td class="c">' + tickets_cell + "</td>" +
				"<td>" + when(r.pilot_last_seen) + "</td>" +
				"<td>" + when(r.im_last_seen) + "</td>" +
				"<td>" + when(r.sim_last_seen) + "</td>" +
			"</tr>";
		}).join("");

		el.wrap.innerHTML =
			"<table><thead><tr>" +
				"<th>IMEI</th><th>Vehicle</th><th>Customer</th><th>ERP status</th>" +
				'<th class="c">Pilot (WSL)</th><th class="c">Pilot 2</th><th class="c">IM</th><th>SIM Status</th>' +
				'<th>Finding</th><th>SIM No</th><th>SIM Type</th><th class="c">Tickets</th>' +
				"<th>Pilot Update</th><th>IM Update</th><th>SIM Update</th>" +
			"</tr>" + filter_row() + "</thead><tbody>" +
			(rows.length ? body : '<tr><td colspan="15" class="fav-empty">' + esc(empty) + "</td></tr>") +
			"</tbody></table>";
		bind_filter_row();
		bind_cell_clicks();
		sync_top_scroll();

		// Paging only when there is more than one page of it.
		if (total > limit) {
			var to = start + rows.length;
			el.foot.innerHTML =
				"<div>" + num(start + 1) + "–" + num(to) + "</div><div>" +
				'<button class="btn btn-default btn-xs" data-p="prev"' + (start <= 0 ? " disabled" : "") + ">Previous</button> " +
				'<button class="btn btn-default btn-xs" data-p="next"' + (to >= total ? " disabled" : "") + ">Next</button></div>";
			el.foot.querySelector('[data-p="prev"]').addEventListener("click", function () {
				start = Math.max(0, start - limit);
				load_rows();
			});
			el.foot.querySelector('[data-p="next"]').addEventListener("click", function () {
				start += limit;
				load_rows();
			});
		} else {
			el.foot.innerHTML = "";
		}
	}

	// ------------------------------------------------------------- actions

	// Fetch All queues a background job that can take about a minute, so
	// there is nothing to await -- this just says "something is happening".
	// Deliberately NOT a percentage: the backend's stage/done/total numbers
	// (see fleet_audit_progress) are meant for a log, not a meter, and a bar
	// that fills unevenly per stage would read as broken rather than honest.
	function set_refreshing(on) {
		el.loadbar.style.display = on ? "" : "none";
		var btn = el.headright.querySelector(".fav-refresh");
		if (btn) {
			btn.disabled = on;
			btn.textContent = on ? "Running…" : "Fetch All";
		}
		if (on && !refresh_watch) {
			// Realtime only reaches the tab that queued the job, so also poll
			// the queue itself -- catches a "done" event this tab missed
			// (reopened mid-run) and a job that died without sending one.
			refresh_watch = setInterval(function () {
				frappe.call({ method: "app_apis.fleet_audit.get_progress" }).then(function (r) {
					if (!((r && r.message) || {}).running) stop_and_reload();
				});
			}, 8000);
		} else if (!on && refresh_watch) {
			clearInterval(refresh_watch);
			refresh_watch = null;
		}
	}

	function stop_and_reload(alert) {
		set_refreshing(false);
		load();
		if (alert) frappe.show_alert(alert);
	}

	function refresh_snapshot() {
		frappe.confirm(
			"Read ERPNext, Pilot and IM again and rebuild the snapshot? Takes about a minute. Nothing is written to any of them.",
			function () {
				frappe.call({
					method: "app_apis.fleet_audit.start_refresh",
					args: { include_im: 1, include_pilot: 1, pilot_source: "admin" },
					callback: function () {
						frappe.show_alert({ message: "Running…", indicator: "blue" });
						set_refreshing(true);
					},
				});
			}
		);
	}

	function upload_sim_file() {
		new frappe.ui.FileUploader({
			folder: "Home",
			// .xlsx only -- the parser (openpyxl) does not read the old .xls format.
			restrictions: { allowed_file_types: [".xlsx"] },
			on_success: function (file_doc) {
				frappe.call({
					method: "app_apis.fleet_audit.import_sim_file",
					args: { file_url: file_doc.file_url },
					freeze: true,
					freeze_message: "Reading the SIM file…",
				}).then(function (r) {
					var d = (r && r.message) || {};
					frappe.show_alert({
						message:
							"SIM file imported: " + num(d.sim_rows) + " SIMs · " +
							num(d.matched_by_imei) + " matched by IMEI · " +
							num(d.matched_by_msisdn) + " more by MSISDN.",
						indicator: "green",
					});
					load();
				});
			},
		});
	}

	function export_csv() {
		frappe.call({
			method: "app_apis.fleet_audit.get_rows",
			args: Object.assign({}, filters, { start: 0, limit: 100000 }),
			freeze: true,
			freeze_message: "Building the file…",
		}).then(function (r) {
			var rows = ((r && r.message) || {}).rows || [];
			if (!rows.length) return frappe.msgprint("Nothing to export.");

			// The per-customer system login emails (Pilot WSL / Pilot 2 / IM)
			// are a second, newer method. If this block's JS is running against
			// an older app_apis that does not define it, the export still has
			// to work -- just drop those three columns. `error_handlers`
			// swallows the "has no attribute" ValidationError; the failure arm
			// of .then() covers anything else.
			call_optional("app_apis.fleet_audit.get_row_emails", null, function (msg, ok) {
				build_and_download(rows, (msg || {}), ok);
			});
		});
	}

	// Runs a whitelisted method that may not exist on an older backend. Never
	// pops an error dialog for a missing method; `cb(message, ok)` always
	// fires, with ok=false when the call failed for any reason.
	function call_optional(method, args, cb) {
		var done = false;
		function finish(msg, ok) { if (!done) { done = true; cb(msg, ok); } }
		try {
			frappe.call({
				method: method,
				args: args || {},
				error_handlers: { ValidationError: function () { finish(null, false); } },
			}).then(
				function (r) { finish(r && r.message, true); },
				function () { finish(null, false); }
			);
		} catch (e) {
			finish(null, false);
		}
	}

	function build_and_download(rows, emails, have_emails) {
		var cols = ["imei", "erp_vehicle", "plate", "customer_name", "erp_status",
			"on_pilot_1", "on_pilot_2", "pilot_last_seen", "pilot_msisdn", "on_im", "im_last_seen",
			"sim_item", "sim_status", "sim_last_seen", "sim_msisdn", "verdict", "issues"];
		if (have_emails) {
			cols = cols.concat(["pilot_wsl_emails", "pilot2_email", "im_platform_email"]);
		}
		function cell(v) {
			return '"' + String(v === null || v === undefined ? "" : v).replace(/"/g, '""') + '"';
		}
		var csv = [cols.join(",")]
			.concat(rows.map(function (row) {
				var merged = Object.assign({}, row, emails[row.name] || {});
				return cols.map(function (c) { return cell(merged[c]); }).join(",");
			}))
			.join("\n");
		var a = document.createElement("a");
		// Leading BOM so Excel reads the Arabic plates and names as UTF-8.
		a.href = "data:text/csv;charset=utf-8," + encodeURIComponent("﻿" + csv);
		a.download = "fleet-audit.csv";
		document.body.appendChild(a);
		a.click();
		document.body.removeChild(a);
	}

	// Realtime updates only reach the current tab/session that queued the job,
	// which is exactly the case where telling the user matters.
	frappe.realtime.on("fleet_audit_progress", function (d) {
		if (d && d.stage === "done") {
			stop_and_reload({ message: "Fleet audit finished.", indicator: "green" });
		}
	});

	load();
	// Covers opening (or reloading) this page while a run someone else
	// started is still going -- there was no "start" event here to react to.
	frappe.call({ method: "app_apis.fleet_audit.get_progress" }).then(function (r) {
		if (((r && r.message) || {}).running) set_refreshing(true);
	});
})();

