.fav .fav-loadbar { height:3px; border-radius:2px; overflow:hidden; position:relative;
	background:var(--control-bg,rgba(120,120,120,.18)); margin-bottom:12px; }
.fav .fav-loadbar-fill { position:absolute; top:0; bottom:0; width:35%; border-radius:2px;
	background:var(--primary,#2490ef); animation:fav-loadbar-sweep 1.1s ease-in-out infinite; }
@keyframes fav-loadbar-sweep { 0% { left:-35%; } 100% { left:100%; } }
.fav .fav-tiles { display:grid; grid-template-columns:repeat(auto-fit,minmax(120px,1fr));
	gap:10px; margin-bottom:16px; }
.fav .fav-tile { background:var(--card-bg); border:1px solid var(--border-color);
	border-radius:var(--border-radius-md,6px); padding:12px 14px; }
.fav .fav-tile .n { font-size:22px; font-weight:600; line-height:1.15; }
.fav .fav-tile .l { font-size:10px; text-transform:uppercase; letter-spacing:.4px;
	color:var(--text-muted); margin-top:3px; }
.fav .fav-note { border-left:3px solid var(--red-500,#e24c4c); background:var(--card-bg);
	border-radius:var(--border-radius-md,6px); padding:9px 12px; margin-bottom:12px;
	font-size:11.5px; line-height:1.5; }
.fav .fav-chips { display:flex; flex-wrap:wrap; gap:6px; margin-bottom:12px; }
.fav .fav-chip { border:1px solid var(--border-color); background:var(--card-bg);
	border-radius:var(--border-radius-md,6px); padding:6px 11px; cursor:pointer;
	display:flex; align-items:center; gap:7px; font-size:11.5px; user-select:none; }
.fav .fav-chip:hover { border-color:var(--gray-500,#8d99a6); }
.fav .fav-chip.on { border-color:var(--primary,#2490ef);
	box-shadow:0 0 0 1px var(--primary,#2490ef) inset; }
.fav .fav-chip .c { font-weight:600; font-size:12px; }
.fav .fav-dot { width:7px; height:7px; border-radius:50%; display:inline-block; }
.fav .fav-bar { display:flex; align-items:center; justify-content:space-between;
	gap:10px; flex-wrap:wrap; margin-bottom:8px; }
.fav .fav-count { font-size:12px; }
.fav tr.fav-filters th { padding:5px 6px; background:var(--control-bg,transparent); }
.fav tr.fav-filters input, .fav tr.fav-filters select {
	width:100%; min-width:70px; height:24px; font-size:11px; padding:1px 5px;
	border:1px solid var(--border-color); border-radius:4px;
	background:var(--card-bg); color:var(--text-color); }
.fav tr.fav-filters input:focus, .fav tr.fav-filters select:focus {
	outline:none; border-color:var(--primary,#2490ef); }
.fav .fav-count b { font-weight:600; }
.fav .fav-clear { font-size:11.5px; }
.fav .fav-topscroll { overflow-x:auto; overflow-y:hidden; height:16px; margin-bottom:2px; }
.fav .fav-topscroll-inner { height:1px; }
.fav .fav-wrap { border:1px solid var(--border-color);
	border-radius:var(--border-radius-md,6px); overflow-x:auto; background:var(--card-bg); }
.fav table { width:100%; margin:0; border-collapse:collapse; font-size:11.5px; }
.fav th { font-size:9.5px; text-transform:uppercase; letter-spacing:.4px;
	color:var(--text-muted); font-weight:600; padding:8px 10px; text-align:left;
	white-space:nowrap; border-bottom:1px solid var(--border-color); }
.fav td { padding:7px 10px; border-bottom:1px solid var(--border-color); }
.fav tr:last-child td { border-bottom:none; }
.fav .c { text-align:center; }
.fav .yes { color:var(--green-600,#17845b); font-weight:600; }
.fav .no  { color:var(--red-600,#b4231b);   font-weight:600; }
.fav .dim { color:var(--text-muted); }
.fav .mono { font-family:var(--font-stack-mono,monospace); font-size:11px; }
.fav .pill { display:inline-block; padding:2px 7px; border-radius:10px;
	font-size:10px; font-weight:600; white-space:nowrap; cursor:help; }
.fav .fav-empty { padding:34px 12px; text-align:center; color:var(--text-muted); }
.fav .fav-foot { display:flex; justify-content:space-between; flex-wrap:wrap; gap:8px;
	margin-top:10px; font-size:11.5px; color:var(--text-muted); }
.fav .fav-round { width:22px; height:22px; padding:0; line-height:1; border-radius:50%;
	border:1px solid var(--border-color); background:var(--card-bg); font-size:11px;
	font-weight:700; display:inline-flex; align-items:center; justify-content:center;
	cursor:default; }
.fav .fav-round-green { color:var(--green-600,#17845b); border-color:var(--green-600,#17845b); }
.fav .fav-round-red { color:var(--red-600,#b4231b); border-color:var(--red-600,#b4231b); }
.fav .fav-round-gray { color:var(--text-muted); }
.fav .fav-round-live { cursor:pointer; }
.fav .fav-round-live:hover { background:var(--control-bg); box-shadow:0 0 0 3px var(--control-bg); }
.fav .fav-round:disabled { opacity:.45; cursor:not-allowed; }
.fav .fav-daterange { display:flex; gap:3px; }
.fav .fav-daterange input[type="date"] { min-width:0; width:50%; padding:1px 2px; font-size:9.5px; }
.fav tr.fav-filters input:disabled { opacity:.45; }
.fav .fav-bar-left { display:flex; align-items:center; gap:14px; flex-wrap:wrap; }
.fav .fav-nosim { display:inline-flex; align-items:center; gap:5px; font-size:11.5px;
	color:var(--text-muted); cursor:pointer; user-select:none; white-space:nowrap; }
.fav .fav-nosim input { margin:0; cursor:pointer; }
